import React from "react";
import {
  useCurrentFrame,
  useVideoConfig,
  AbsoluteFill,
  interpolate,
  spring,
} from '../remotionShim';
import { makeLoadFont } from '../googleFonts';
const loadInter = makeLoadFont('Inter');

// Library: none — native interpolate and De Casteljau bezier math used for tip riders

const { fontFamily: interFamily } = loadInter();



export type GraphAnimationProps = Record<string, any>;

// Bezier Math helper
const L = (a: number, b: number, t: number) => a + (b - a) * t;

type Point = { x: number; y: number };

const splitBezier = (p0: Point, p1: Point, p2: Point, p3: Point, t: number) => {
  if (t <= 0) {
    return {
      path: `M ${p0.x} ${p0.y}`,
      tip: p0,
      angle: Math.atan2(p1.y - p0.y, p1.x - p0.x) * (180 / Math.PI),
    };
  }
  if (t >= 1) {
    return {
      path: `M ${p0.x} ${p0.y} C ${p1.x} ${p1.y}, ${p2.x} ${p2.y}, ${p3.x} ${p3.y}`,
      tip: p3,
      angle: Math.atan2(p3.y - p2.y, p3.x - p2.x) * (180 / Math.PI),
    };
  }

  const ax = L(p0.x, p1.x, t);
  const ay = L(p0.y, p1.y, t);
  const bx = L(p1.x, p2.x, t);
  const by = L(p1.y, p2.y, t);
  const cx = L(p2.x, p3.x, t);
  const cy = L(p2.y, p3.y, t);

  const dx = L(ax, bx, t);
  const dy = L(ay, by, t);
  const ex = L(bx, cx, t);
  const ey = L(by, cy, t);

  const fx = L(dx, ex, t);
  const fy = L(dy, ey, t);

  return {
    path: `M ${p0.x} ${p0.y} C ${ax} ${ay}, ${dx} ${dy}, ${fx} ${fy}`,
    tip: { x: fx, y: fy },
    angle: Math.atan2(fy - dy, fx - dx) * (180 / Math.PI),
  };
};

const GraphAnimation: React.FC<GraphAnimationProps> = ({
  backgroundColor = "#111215",
  transparentBackground = false,
  durationInSeconds = 3,
  gridColor = "#2c2c30",
  pinkColor = "#ff7b9c",
  greenColor = "#54d375",
  textColor = "#ffffff",
  titleLine1 = "WHAT CLOTHING",
  titleLine2Start = "BRANDS",
  titleLine2Pink = "FOCUS ON",
  titleLine3 = "VS.",
  titleLine4 = "WHAT ACTUALLY",
  titleLine5Green = "GROWS THEM",
  yAxisLabel = "BRAND GROWTH",
  xAxisLabel = "TIME",
  legendPinkLabel = "LOOKING LIKE A BRAND",
  legendGreenLabel = "BUILDING A REAL BRAND",
  pinkCalloutTitle = "LOOKS GOOD",
  pinkCalloutBody = "But nobody cares yet.",
  greenCalloutTitle = "REAL MOMENTUM",
  greenCalloutBody = "Trust begins\nturning into sales.",
}) => {
  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();
  const s = Math.min(width, height) / 1080;

  const bgColor = transparentBackground ? `${backgroundColor}00` : backgroundColor;

  // Timings
  const baseEntranceEnd = 15;
  const pinkStart = 10;
  const pinkEnd = 50;
  const greenStart = 25;
  const greenEnd = 80;

  const pinkProgress = interpolate(frame, [pinkStart, pinkEnd], [0, 1], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });
  
  const greenProgress = interpolate(frame, [greenStart, greenEnd], [0, 1], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });

  const baseOpacity = interpolate(frame, [0, baseEntranceEnd], [0, 1], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });

  // Graph Area Dimensions
  const graphW = width * 0.8;
  const graphH = height * 0.45;
  const graphX = width * 0.15;
  const graphY = height * 0.35;

  // Path Definitions (Relative to Graph Box)
  const pinkP0: Point = { x: 0, y: graphH * 0.9 };
  const pinkP1: Point = { x: graphW * 0.05, y: -graphH * 0.2 };
  const pinkP2: Point = { x: graphW * 0.4, y: graphH * 0.4 };
  const pinkP3: Point = { x: graphW, y: graphH * 0.85 };

  const greenP0: Point = { x: 0, y: graphH * 0.95 };
  const greenP1: Point = { x: graphW * 0.5, y: graphH * 0.85 };
  const greenP2: Point = { x: graphW * 0.6, y: graphH * 0.35 };
  const greenP3: Point = { x: graphW, y: graphH * 0.05 };

  const pinkLineData = splitBezier(pinkP0, pinkP1, pinkP2, pinkP3, pinkProgress);
  const greenLineData = splitBezier(greenP0, greenP1, greenP2, greenP3, greenProgress);

  // Callout static positions (calculated fully once for placement)
  const pinkCalloutT = 0.25;
  const greenCalloutT = 0.68;
  const pinkCalloutTarget = splitBezier(pinkP0, pinkP1, pinkP2, pinkP3, pinkCalloutT).tip;
  const greenCalloutTarget = splitBezier(greenP0, greenP1, greenP2, greenP3, greenCalloutT).tip;

  // Callout Entrance Animations
  const pinkCalloutVisible = pinkProgress >= pinkCalloutT;
  const greenCalloutVisible = greenProgress >= greenCalloutT;
  
  const pinkCalloutPop = spring({
    fps,
    frame: pinkCalloutVisible ? frame - (pinkStart + (pinkEnd - pinkStart) * pinkCalloutT) : 0,
    config: { damping: 14, stiffness: 120 },
  });

  const greenCalloutPop = spring({
    fps,
    frame: greenCalloutVisible ? frame - (greenStart + (greenEnd - greenStart) * greenCalloutT) : 0,
    config: { damping: 14, stiffness: 120 },
  });

  // Grid Construction
  const hLines = 8;
  const vLines = 8;
  const gridPaths = [];
  for (let i = 0; i <= hLines; i++) {
    const y = (graphH / hLines) * i;
    gridPaths.push(`M 0 ${y} L ${graphW} ${y}`);
  }
  for (let i = 0; i <= vLines; i++) {
    const x = (graphW / vLines) * i;
    gridPaths.push(`M ${x} 0 L ${x} ${graphH}`);
  }

  // Arrowhead Component
  const Arrowhead = ({ x, y, angle, color, size = 18 * s }: any) => (
    <polygon
      points={`0,${-size/2} ${size},0 0,${size/2}`}
      fill={color}
      transform={`translate(${x}, ${y}) rotate(${angle}) translate(${-size}, 0)`}
      style={{ transition: "none" }}
    />
  );

  return (
    <AbsoluteFill
      style={{
        backgroundColor: bgColor,
        fontFamily: interFamily,
        color: textColor,
      }}
    >
      {/* --- TITLE AREA --- */}
      <div
        style={{
          position: "absolute",
          top: height * 0.08,
          left: 0,
          width: "100%",
          display: "flex",
          flexDirection: "column",
          alignItems: "center",
          fontWeight: 900,
          fontSize: 72 * s,
          lineHeight: 1.1,
          letterSpacing: "-0.02em",
          opacity: baseOpacity,
          transition: "none",
        }}
      >
        <div>{titleLine1}</div>
        <div style={{ display: "flex", gap: 16 * s }}>
          <span>{titleLine2Start}</span>
          <span style={{ color: pinkColor }}>{titleLine2Pink}</span>
        </div>
        <div>{titleLine3}</div>
        <div>{titleLine4}</div>
        <div style={{ color: greenColor }}>{titleLine5Green}</div>
      </div>

      {/* --- GRAPH AREA --- */}
      <div
        style={{
          position: "absolute",
          left: graphX,
          top: graphY,
          width: graphW,
          height: graphH,
          opacity: baseOpacity,
          transition: "none",
        }}
      >
        <svg
          width={graphW}
          height={graphH}
          viewBox={`0 0 ${graphW} ${graphH}`}
          style={{ overflow: "visible" }}
        >
          {/* Grid */}
          <path
            d={gridPaths.join(" ")}
            stroke={gridColor}
            strokeWidth={2 * s}
            fill="none"
            strokeDasharray={`${6 * s},${6 * s}`}
          />

          {/* Axes */}
          <path
            d={`M 0 0 L 0 ${graphH} L ${graphW} ${graphH}`}
            stroke={textColor}
            strokeWidth={4 * s}
            fill="none"
          />
          {/* Axis Arrows */}
          <polygon
            points={`0,${-12*s} ${16*s},0 0,${12*s}`}
            fill={textColor}
            transform={`translate(0, 0) rotate(-90) translate(${-16*s}, 0)`}
          />
          <polygon
            points={`0,${-12*s} ${16*s},0 0,${12*s}`}
            fill={textColor}
            transform={`translate(${graphW}, ${graphH}) rotate(0)`}
          />

          {/* Pink Line */}
          {pinkProgress > 0 && (
            <g style={{ transition: "none" }}>
              <path
                d={pinkLineData.path}
                stroke={pinkColor}
                strokeWidth={8 * s}
                fill="none"
                strokeLinecap="round"
                strokeLinejoin="round"
                style={{ transition: "none" }}
              />
              <Arrowhead
                x={pinkLineData.tip.x}
                y={pinkLineData.tip.y}
                angle={pinkLineData.angle}
                color={pinkColor}
                size={24 * s}
              />
            </g>
          )}

          {/* Green Line */}
          {greenProgress > 0 && (
            <g style={{ transition: "none" }}>
              <path
                d={greenLineData.path}
                stroke={greenColor}
                strokeWidth={8 * s}
                fill="none"
                strokeLinecap="round"
                strokeLinejoin="round"
                style={{ transition: "none" }}
              />
              <Arrowhead
                x={greenLineData.tip.x}
                y={greenLineData.tip.y}
                angle={greenLineData.angle}
                color={greenColor}
                size={24 * s}
              />
            </g>
          )}

          {/* Pink Callout Line & Dot */}
          <g
            style={{
              opacity: pinkCalloutPop,
              transform: `scale(${pinkCalloutPop})`,
              transformOrigin: `${pinkCalloutTarget.x}px ${pinkCalloutTarget.y}px`,
              transition: "none",
            }}
          >
            <path
              d={`M ${pinkCalloutTarget.x} ${pinkCalloutTarget.y} L ${pinkCalloutTarget.x - 40 * s} ${pinkCalloutTarget.y - 60 * s}`}
              stroke={textColor}
              strokeWidth={2 * s}
              fill="none"
            />
            <circle
              cx={pinkCalloutTarget.x}
              cy={pinkCalloutTarget.y}
              r={10 * s}
              fill={backgroundColor}
              stroke={textColor}
              strokeWidth={4 * s}
            />
          </g>

          {/* Green Callout Line & Dot */}
          <g
            style={{
              opacity: greenCalloutPop,
              transform: `scale(${greenCalloutPop})`,
              transformOrigin: `${greenCalloutTarget.x}px ${greenCalloutTarget.y}px`,
              transition: "none",
            }}
          >
            <path
              d={`M ${greenCalloutTarget.x} ${greenCalloutTarget.y} L ${greenCalloutTarget.x + 40 * s} ${greenCalloutTarget.y - 40 * s}`}
              stroke={textColor}
              strokeWidth={2 * s}
              fill="none"
            />
            <circle
              cx={greenCalloutTarget.x}
              cy={greenCalloutTarget.y}
              r={10 * s}
              fill={backgroundColor}
              stroke={textColor}
              strokeWidth={4 * s}
            />
          </g>
        </svg>

        {/* Pink Callout Text */}
        <div
          style={{
            position: "absolute",
            left: pinkCalloutTarget.x - 40 * s,
            top: pinkCalloutTarget.y - 60 * s,
            transform: `translate(-10%, -100%) scale(${pinkCalloutPop})`,
            transformOrigin: "bottom left",
            opacity: pinkCalloutPop,
            display: "flex",
            flexDirection: "column",
            minWidth: 300 * s,
            transition: "none",
          }}
        >
          <div style={{ color: pinkColor, fontWeight: 700, fontSize: 32 * s }}>
            {pinkCalloutTitle}
          </div>
          <div style={{ color: textColor, fontSize: 24 * s, marginTop: 4 * s, whiteSpace: "pre-wrap" }}>
            {pinkCalloutBody}
          </div>
        </div>

        {/* Green Callout Text */}
        <div
          style={{
            position: "absolute",
            left: greenCalloutTarget.x + 40 * s,
            top: greenCalloutTarget.y - 40 * s,
            transform: `translate(10%, -100%) scale(${greenCalloutPop})`,
            transformOrigin: "bottom left",
            opacity: greenCalloutPop,
            display: "flex",
            flexDirection: "column",
            minWidth: 300 * s,
            transition: "none",
          }}
        >
          <div style={{ color: greenColor, fontWeight: 700, fontSize: 32 * s }}>
            {greenCalloutTitle}
          </div>
          <div style={{ color: textColor, fontSize: 24 * s, marginTop: 4 * s, whiteSpace: "pre-wrap" }}>
            {greenCalloutBody}
          </div>
        </div>

        {/* Axis Labels */}
        <div
          style={{
            position: "absolute",
            left: -40 * s,
            top: graphH / 2,
            transform: "translate(-100%, -50%) rotate(-90deg)",
            fontWeight: 700,
            fontSize: 28 * s,
            letterSpacing: "0.05em",
            whiteSpace: "nowrap",
          }}
        >
          {yAxisLabel}
        </div>
        <div
          style={{
            position: "absolute",
            left: graphW / 2,
            top: graphH + 30 * s,
            transform: "translateX(-50%)",
            fontWeight: 700,
            fontSize: 28 * s,
            letterSpacing: "0.05em",
          }}
        >
          {xAxisLabel}
        </div>
      </div>

      {/* --- LEGEND --- */}
      <div
        style={{
          position: "absolute",
          top: graphY + graphH + 180 * s,
          left: 0,
          width: "100%",
          display: "flex",
          flexDirection: "column",
          alignItems: "center",
          gap: 32 * s,
          opacity: baseOpacity,
          transition: "none",
        }}
      >
        <div style={{ display: "flex", alignItems: "center", gap: 24 * s }}>
          <div
            style={{
              width: 100 * s,
              height: 8 * s,
              backgroundColor: pinkColor,
              borderRadius: 4 * s,
            }}
          />
          <div style={{ fontSize: 32 * s, fontWeight: 700 }}>
            {legendPinkLabel}
          </div>
        </div>
        <div style={{ display: "flex", alignItems: "center", gap: 24 * s }}>
          <div
            style={{
              width: 100 * s,
              height: 8 * s,
              backgroundColor: greenColor,
              borderRadius: 4 * s,
            }}
          />
          <div style={{ fontSize: 32 * s, fontWeight: 700 }}>
            {legendGreenLabel}
          </div>
        </div>
      </div>
    </AbsoluteFill>
  );
};

export default GraphAnimation;